#include "ryml.hpp"
#include "ryml_std.hpp"
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
static ryml::ConstNodeRef child(const ryml::ConstNodeRef&n,const char*k){return n.find_child(ryml::to_csubstr(k));}
template<class V>static void read(const ryml::ConstNodeRef&n,const char*k,V&v){auto c=child(n,k);if(c.valid())c>>v;}
static std::string text(const ryml::ConstNodeRef&n){auto v=n.val();return {v.str,v.len};}
static ryml::Tree parse(const char*p){std::ifstream i(p,std::ios::binary);std::ostringstream b;b<<i.rdbuf();auto y=b.str();return ryml::parse_in_arena(ryml::to_csubstr(p),ryml::to_csubstr(y));}
struct State{int ground=5,zone=0,alt=0,speed=0,waveCount=0,waveTimer=0,missionWeight=0,raceWeight=0,regionWeight=0,arcFirst=0,arcLast=-1,arcWeight=0,counter=0,eventWeight=0,maxRuns=-1,scriptWeight=0,adhoc=0,articleType=0,articleOrder=0,pages=1,everyItems=0;bool objective=false,multi=false,stats=false;std::string description,spawned,title="ITEM",page0,page1;};
static void apply(const ryml::ConstNodeRef&root,State&s,int&articleCounter){auto ts=child(root,"ufoTrajectories");if(ts.valid())for(auto n:ts){read(n,"groundTimer",s.ground);auto w=child(n,"waypoints");if(w.valid()&&w.num_children()){w[0][0]>>s.zone;w[0][1]>>s.alt;w[0][2]>>s.speed;}}
auto ms=child(root,"alienMissions");if(ms.valid())for(auto n:ms){auto waves=child(n,"waves");if(waves.valid()&&waves.num_children()){read(waves[0],"count",s.waveCount);read(waves[0],"timer",s.waveTimer);read(waves[0],"objective",s.objective);}auto mw=child(n,"missionWeights");if(mw.valid())read(mw,"0",s.missionWeight);auto rw=child(n,"raceWeights");if(rw.valid()){auto z=child(rw,"0");int zero=1;read(z,"RACE",zero);if(zero==0)s.raceWeight=0;read(z,"RACE",s.raceWeight);read(z,"RACE_2",s.raceWeight);}auto reg=child(n,"regionWeights");if(reg.valid())read(child(reg,"0"),"REGION",s.regionWeight);bool extra=false;read(n,"multiUfoRetaliationExtra",extra);if(extra)s.multi=true;}
auto arcs=child(root,"arcScripts");if(arcs.valid())for(auto n:arcs){read(n,"firstMonth",s.arcFirst);read(n,"lastMonth",s.arcLast);read(child(n,"randomArcs"),"RESEARCH",s.arcWeight);}auto events=child(root,"events");if(events.valid())for(auto n:events){read(n,"description",s.description);auto items=child(n,"everyItemList");if(items.valid())s.everyItems=(int)items.num_children();auto soldier=child(n,"spawnedSoldier");if(soldier.valid()){read(soldier,"name",s.spawned);if(child(soldier,"stats").valid())s.stats=true;}}
auto es=child(root,"eventScripts");if(es.valid())for(auto n:es){read(n,"missionMinRuns",s.counter);read(n,"counterMin",s.counter);auto ew=child(n,"eventWeights");if(ew.valid())read(child(ew,"0"),"EVENT",s.eventWeight);}auto scripts=child(root,"missionScripts");if(scripts.valid())for(auto n:scripts){read(n,"maxRuns",s.maxRuns);auto mw=child(n,"missionWeights");if(mw.valid())read(child(mw,"0"),"MISSION",s.scriptWeight);}auto adhoc=child(root,"adhocScripts");if(adhoc.valid())for(auto n:adhoc){auto tags=child(n,"adhocMissionScriptTags");if(tags.valid())s.adhoc=(int)tags.num_children();}
auto articles=child(root,"ufopaedia");if(articles.valid())for(auto n:articles){auto del=child(n,"delete");if(del.valid())continue;auto id=child(n,"id");if(!id.valid())continue;++articleCounter;auto value=text(id);if(value!="ITEM")continue;read(n,"type_id",s.articleType);if(!s.articleOrder)s.articleOrder=articleCounter*100;read(n,"title",s.title);read(n,"text",s.page0);auto pages=child(n,"pages");if(pages.valid()){s.pages=(int)pages.num_children();if(s.pages>0){read(pages[0],"title",s.title);std::string t=s.page0;read(pages[0],"text",t);s.page0=t;}if(s.pages>1){s.page1=s.page0;read(pages[1],"text",s.page1);}}}}
int main(int argc,char**argv){if(argc!=3)return 2;State s;int order=0;auto a=parse(argv[1]);auto b=parse(argv[2]);apply(a.crootref(),s,order);apply(b.crootref(),s,order);std::cout<<"{\"adhoc\":["<<s.adhoc<<"],\"alienMission\":["<<s.waveCount<<','<<s.waveTimer<<','<<(s.objective?"true":"false")<<','<<s.missionWeight<<','<<(s.multi?"true":"false")<<','<<s.raceWeight<<','<<s.regionWeight<<"],\"arc\":["<<s.arcFirst<<','<<s.arcLast<<','<<s.arcWeight<<"],\"article\":["<<s.articleType<<','<<s.articleOrder<<','<<s.pages<<",\""<<s.title<<"\",\""<<s.page0<<"\",\""<<s.page1<<"\"],\"event\":[\""<<s.description<<"\","<<s.everyItems<<",\""<<s.spawned<<"\","<<(s.stats?"true":"false")<<"],\"eventScript\":["<<s.counter<<','<<s.eventWeight<<"],\"missionScript\":["<<s.maxRuns<<','<<s.scriptWeight<<"],\"trajectory\":["<<s.ground<<",1,"<<s.zone<<','<<s.alt<<','<<s.speed<<"]}\n";}
